t=k*Mathf.PI*2/sides,z=(k+1)*Mathf.PI*2/sides;var x=r*(u*Mathf.Cos(t)+w*Mathf.Sin(t));var y=r*(u*Mathf.Cos(z)+w*Mathf.Sin(z));Tri(a+x,a+y,b+x,color,tex,glow);Tri(a+y,b+y,b+x,color,tex,glow);Tri(a,a+y,a+x,color,tex,glow);Tri(b,b+x,b+y,color,tex,glow);}}public Mesh Save(string n){var m=new Mesh{name=n};m.SetVertices(p);m.SetUVs(0,uv);m.SetUVs(1,flags);m.SetColors(c);m.SetTriangles(ids,0);m.RecalculateNormals();m.RecalculateTangents();m.RecalculateBounds();m.Optimize();AssetDatabase.CreateAsset(m,D+"/"+n+".asset");return m;}}
